/* Bodriostars - todo en un archivo: el servidor y la pagina del juego.
   La pagina esta al final, en la constante PAGINA. */

/* Bodriostars — servidor en Cloudflare Workers + Durable Objects.

   Dos piezas:
   - Cuentas  : UN objeto para todo el juego. Guarda las cuentas (SQLite) y la
                lista de salas abiertas. Es el que atiende /ws.
   - Sala     : UN objeto por sala. Atiende /sala/CODIGO y lleva esa partida:
                quién está, quién es el anfitrión y el ida y vuelta de mensajes.

   Así, por más salas que haya, los de una misma sala siempre caen en el mismo
   objeto, y las cuentas son únicas para todos. */

const MAX_SALA = 6;            // jugadores por sala (3 contra 3). Subilo cuando haya modos más grandes.
const MAX_LOBBY = 300;         // gente conectada a la vez al lobby
const MAX_MSG = 256 * 1024;    // tamaño máximo de un mensaje
const LETRAS = 'ABCDEFGHJKLMNPQRSTUVWXYZ';   // sin I ni O

/* ---- tienda ---- */
const PRECIOS = { brasa: 0, chispa: 40, vela: 70, filo: 120, tosca: 150, ronin: 200 };
const INICIAL = 'brasa';                       // con el que arranca todo el mundo
const PAGA = { jugar: 10, ganar: 0, ko: 0 };   // 10 monedas por partida jugada
const TOPE_KO = 20;                            // no contamos más KOs que esto por partida

/* ---- administrador ---- */
const ADMIN = 'sepita';
const ADMIN_HASH = '2df9c16fed9cb743c37bf636cbea0ef06c704a08a7f6ba9ef5a67f620694218b';

const json = o => new Response(JSON.stringify(o), { headers: { 'Content-Type': 'application/json' } });

async function hashear(s) {
  const b = await crypto.subtle.digest('SHA-256', new TextEncoder().encode('bodrio:' + s));
  return [...new Uint8Array(b)].map(x => x.toString(16).padStart(2, '0')).join('');
}

/* ================= Cuentas: cuentas + lista de salas ================= */
export class Cuentas {
  constructor(ctx) {
    this.ctx = ctx;
    this.sql = ctx.storage.sql;
    this.sql.exec(`CREATE TABLE IF NOT EXISTS cuentas(
      nombre TEXT PRIMARY KEY, partidas INTEGER DEFAULT 0, ganadas INTEGER DEFAULT 0,
      kos INTEGER DEFAULT 0, caidas INTEGER DEFAULT 0, danio INTEGER DEFAULT 0, ultima TEXT)`);
    // columnas que se agregaron después (contraseña y tienda): si ya están, el ALTER falla y no pasa nada
    for (const col of ['pass TEXT', 'monedas INTEGER DEFAULT 0', 'tengo TEXT', 'admin INTEGER DEFAULT 0', 'modo INTEGER DEFAULT 0'])
      try { this.sql.exec('ALTER TABLE cuentas ADD COLUMN ' + col); } catch (e) {}
    this.sql.exec(`CREATE TABLE IF NOT EXISTS amigos(
      de TEXT, para TEXT, estado TEXT, PRIMARY KEY (de, para))`);
    this.salas = new Map();     // código -> { code, host, players, max, playing, visto, nombres }
  }

  async fetch(req) {
    const url = new URL(req.url);

    if (url.pathname === '/aviso') {               // una sala nos cuenta cómo está
      const m = await req.json();
      if (m.vacia) this.salas.delete(m.code);
      else this.salas.set(m.code, { code: m.code, host: m.host, players: m.players, max: m.max, playing: !!m.playing, visto: Date.now(), nombres: m.nombres || [] });
      this.avisarSalas();
      this.avisarAmigos();
      return json({ ok: true });
    }
    if (url.pathname === '/resultado') {           // una sala terminó: guardamos, pagamos y avisamos
      const m = await req.json();
      const pagos = this.guardarResultado(m.players);
      const t = JSON.stringify({ t: 'scores', table: this.tabla() });
      for (const w of this.ctx.getWebSockets()) {
        try {
          w.send(t);
          const n = this.datos(w).name;
          if (n && pagos[n.toLowerCase()] != null) this.enviar(w, this.billetera(n, { gane: pagos[n.toLowerCase()] }));
        } catch (e) {}
      }
      return json({ ok: true });
    }
    if (url.pathname === '/codigo') {              // una sala nueva pide código libre
      let c;
      do { c = Array.from({ length: 4 }, () => LETRAS[Math.floor(Math.random() * LETRAS.length)]).join(''); }
      while (this.salas.has(c));
      this.salas.set(c, { code: c, host: '?', players: 0, max: MAX_SALA, playing: false, visto: Date.now() });
      return json({ code: c });
    }
    if (url.pathname === '/entrar') {              // una sala pregunta si esa cuenta existe
      const m = await req.json();
      const f = this.ficha(String(m.name || '').slice(0, 14));
      return json(f ? { ok: true, name: f.nombre, tengo: this.tengoDe(f) } : { err: 'Esa cuenta no existe.' });
    }

    if (req.headers.get('Upgrade') !== 'websocket') return new Response('Acá va un WebSocket', { status: 426 });
    if (this.ctx.getWebSockets().length >= MAX_LOBBY) return new Response('Servidor lleno', { status: 503 });

    const par = new WebSocketPair();
    this.ctx.acceptWebSocket(par[1]);
    const id = ((await this.ctx.storage.get('seq')) || 0) + 1;
    await this.ctx.storage.put('seq', id);
    par[1].serializeAttachment({ id, name: '' });
    this.enviar(par[1], { t: 'hello', id });
    this.enviar(par[1], { t: 'scores', table: this.tabla() });
    this.enviar(par[1], { t: 'rooms', list: this.listaSalas() });
    return new Response(null, { status: 101, webSocket: par[0] });
  }

  datos(ws) { try { return ws.deserializeAttachment() || {}; } catch (e) { return {}; } }
  enviar(ws, o) { try { ws.send(JSON.stringify(o)); } catch (e) {} }
  listaSalas() {
    const corte = Date.now() - 5 * 60 * 1000;      // una sala sin noticias en 5 minutos se cae de la lista
    for (const [c, r] of this.salas) if (r.visto < corte || r.players <= 0) this.salas.delete(c);
    return [...this.salas.values()]
      .map(({ visto, ...r }) => r)
      .sort((a, b) => a.code.localeCompare(b.code));
  }
  avisarSalas() {
    const msg = JSON.stringify({ t: 'rooms', list: this.listaSalas() });
    for (const w of this.ctx.getWebSockets()) if (this.datos(w).name) { try { w.send(msg); } catch (e) {} }
  }
  tabla() {
    return this.sql.exec(`SELECT nombre, partidas, ganadas, kos FROM cuentas
      ORDER BY ganadas DESC, kos DESC, nombre ASC LIMIT 20`).toArray()
      .map(f => ({ name: f.nombre, partidas: f.partidas, ganadas: f.ganadas, kos: f.kos }));
  }
  ficha(nombre) {
    return this.sql.exec('SELECT * FROM cuentas WHERE nombre = ?', nombre).toArray()[0] || null;
  }
  manda(f) { return !!(f && f.admin && !f.modo); }         // admin de verdad y no está mirando "como jugador"
  tengoDe(f) {
    let t = [];
    try { t = JSON.parse(f && f.tengo || '[]'); } catch (e) {}
    if (!Array.isArray(t)) t = [];
    t = t.filter(k => k in PRECIOS);
    if (!t.includes(INICIAL)) t.unshift(INICIAL);          // el inicial no se pierde nunca
    if (this.manda(f)) t = Object.keys(PRECIOS);           // el admin tiene todo
    return t;
  }
  billetera(nombre, extra) {
    const f = this.ficha(nombre);
    if (!f) return null;
    return {
      t: 'billetera', monedas: this.manda(f) ? 999999 : (f.monedas | 0), tengo: this.tengoDe(f),
      admin: this.manda(f), jefe: !!f.admin,
      stats: { partidas: f.partidas | 0, ganadas: f.ganadas | 0, kos: f.kos | 0 },
      ...(extra || {})
    };
  }

  /* ---------- amigos ---------- */
  socketDe(nombre) {
    const n = String(nombre || '').toLowerCase();
    for (const w of this.ctx.getWebSockets()) if ((this.datos(w).name || '').toLowerCase() === n) return w;
    return null;
  }
  salaDe(nombre) {
    const n = String(nombre || '').toLowerCase();
    for (const r of this.salas.values()) if ((r.nombres || []).some(x => String(x).toLowerCase() === n)) return r;
    return null;
  }
  listaAmigos(yo) {
    const fila = this.sql.exec('SELECT de, para, estado FROM amigos WHERE de = ? OR para = ?', yo, yo).toArray();
    const lista = [], pedidos = [], enviados = [];
    for (const r of fila) {
      const otro = r.de === yo ? r.para : r.de;
      if (r.estado === 'ok') {
        const s = this.salaDe(otro);
        lista.push({ name: otro, online: !!this.socketDe(otro), sala: s && !s.playing ? s.code : null, jugando: !!(s && s.playing) });
      }
      else if (r.de === yo) enviados.push(otro);
      else pedidos.push(otro);
    }
    lista.sort((a, b) => (b.online - a.online) || a.name.localeCompare(b.name));
    return { t: 'amigos', lista, pedidos, enviados };
  }
  mandarAmigos(nombre) {
    const w = this.socketDe(nombre);
    if (w) this.enviar(w, this.listaAmigos(nombre));
  }
  avisarAmigos() {                       // algo cambió en las salas: refrescamos a todos los conectados
    for (const w of this.ctx.getWebSockets()) {
      const n = this.datos(w).name;
      if (n) this.enviar(w, this.listaAmigos(n));
    }
  }
  async entrar(nombre, pass, crear) {
    nombre = String(nombre || '').trim().slice(0, 14);
    pass = String(pass == null ? '' : pass);
    if (nombre.length < 2) return { err: 'El nombre tiene que tener al menos 2 letras.' };
    if (pass.length < 4) return { err: 'La contraseña tiene que tener al menos 4 caracteres.' };
    const h = await hashear(pass);
    const esAdmin = nombre.toLowerCase() === ADMIN;
    if (esAdmin && h !== ADMIN_HASH) return { err: 'Ese nombre está reservado.' };
    const f = this.ficha(nombre);
    if (!f) {
      if (crear === false) return { err: 'No existe ninguna cuenta con ese nombre. Tocá «Crear cuenta».' };
      this.sql.exec('INSERT INTO cuentas (nombre, pass, monedas, tengo, admin) VALUES (?, ?, 0, ?, ?)',
        nombre, h, JSON.stringify([INICIAL]), esAdmin ? 1 : 0);
      return { ok: true, name: nombre, nueva: true };
    }
    if (crear === true && f.pass) return { err: 'Ya hay una cuenta con ese nombre. Si es tuya, tocá «Entrar».' };
    if (!f.pass) this.sql.exec('UPDATE cuentas SET pass = ? WHERE nombre = ?', h, nombre);  // cuenta vieja, sin contraseña: se queda con la primera que pongan
    else if (f.pass !== h) return { err: 'Contraseña incorrecta. Si no es tu cuenta, elegí otro nombre.' };
    if (esAdmin) this.sql.exec('UPDATE cuentas SET admin = 1, modo = 0 WHERE nombre = ?', nombre);  // entra siempre con todos los poderes
    return { ok: true, name: nombre, nueva: false };
  }
  guardarResultado(players) {
    const pagos = {};
    for (const p of players || []) {
      const n = String(p.name || '').slice(0, 14);
      const f = n && this.ficha(n);
      if (!f) continue;
      const ko = Math.max(0, Math.min(TOPE_KO, p.ko | 0));
      const gana = PAGA.jugar + (p.won ? PAGA.ganar : 0) + ko * PAGA.ko;
      this.sql.exec(`UPDATE cuentas SET partidas = partidas + 1, ganadas = ganadas + ?,
        kos = kos + ?, caidas = caidas + ?, danio = danio + ?, monedas = monedas + ?, ultima = ? WHERE nombre = ?`,
        p.won ? 1 : 0, ko, p.deaths | 0, p.dmg | 0, gana, new Date().toISOString().slice(0, 10), n);
      pagos[n.toLowerCase()] = gana;
    }
    return pagos;
  }

  async webSocketMessage(ws, raw) {
    if (typeof raw !== 'string' || raw.length > MAX_MSG) return;
    let m; try { m = JSON.parse(raw); } catch (e) { return; }
    const yo = this.datos(ws);
    switch (m.t) {
      case 'login': {
        const r = await this.entrar(m.name, m.pass, typeof m.crear === 'boolean' ? m.crear : undefined);
        if (r.err) { this.enviar(ws, { t: 'loginerr', msg: r.err }); return; }
        for (const w of this.ctx.getWebSockets()) {
          if (w === ws) continue;
          const n = this.datos(w).name;
          if (n && n.toLowerCase() === r.name.toLowerCase()) {
            this.enviar(ws, { t: 'loginerr', msg: 'Ese nombre lo está usando alguien más ahora mismo. Probá con otro.' });
            return;
          }
        }
        ws.serializeAttachment({ ...yo, name: r.name });
        this.enviar(ws, { t: 'loginok', name: r.name, nueva: r.nueva });
        this.enviar(ws, this.billetera(r.name));
        this.enviar(ws, { t: 'scores', table: this.tabla() });
        this.enviar(ws, { t: 'rooms', list: this.listaSalas() });
        this.enviar(ws, this.listaAmigos(r.name));
        this.avisarAmigos();
        break;
      }
      case 'comprar': {                              // la compra la decide el servidor, no el navegador
        if (!yo.name) return;
        const k = String(m.char || '');
        const f = this.ficha(yo.name);
        if (!f || !(k in PRECIOS)) return;
        const tengo = this.tengoDe(f);
        if (tengo.includes(k)) { this.enviar(ws, this.billetera(yo.name)); return; }
        const precio = PRECIOS[k];
        if (!this.manda(f) && (f.monedas | 0) < precio) {
          this.enviar(ws, this.billetera(yo.name, { aviso: 'Te faltan ' + (precio - (f.monedas | 0)) + ' monedas.' }));
          return;
        }
        tengo.push(k);
        this.sql.exec('UPDATE cuentas SET monedas = monedas - ?, tengo = ? WHERE nombre = ?',
          this.manda(f) ? 0 : precio, JSON.stringify(tengo), yo.name);
        this.enviar(ws, this.billetera(yo.name, { compre: k }));
        break;
      }
      case 'adm': {                                  // herramientas del administrador
        if (!yo.name) return;
        const f = this.ficha(yo.name);
        if (!f || !f.admin) return;                  // ojo: el flag crudo, así siempre puede volver
        if (m.que === 'monedas') this.sql.exec('UPDATE cuentas SET monedas = monedas + 1000 WHERE nombre = ?', yo.name);
        if (m.que === 'reset') this.sql.exec('UPDATE cuentas SET tengo = ?, monedas = 0 WHERE nombre = ?', JSON.stringify([INICIAL]), yo.name);
        if (m.que === 'probar') this.sql.exec('UPDATE cuentas SET modo = ? WHERE nombre = ?', f.modo ? 0 : 1, yo.name);
        this.enviar(ws, this.billetera(yo.name));
        break;
      }
      case 'rooms':
        if (yo.name) this.enviar(ws, { t: 'rooms', list: this.listaSalas() });
        break;
      case 'create': {
        if (!yo.name) return;
        let c;
        do { c = Array.from({ length: 4 }, () => LETRAS[Math.floor(Math.random() * LETRAS.length)]).join(''); }
        while (this.salas.has(c));
        this.salas.set(c, { code: c, host: yo.name, players: 0, max: MAX_SALA, playing: false, visto: Date.now() });
        this.enviar(ws, { t: 'room', code: c });
        this.avisarSalas();
        break;
      }
      case 'amigos': if (yo.name) this.enviar(ws, this.listaAmigos(yo.name)); break;
      case 'amigo': {
        if (!yo.name) return;
        const otro = String(m.name || '').trim().slice(0, 14);
        if (!otro || otro.toLowerCase() === yo.name.toLowerCase()) { this.enviar(ws, { t: 'amigoerr', msg: 'Ese sos vos.' }); return; }
        const f = this.ficha(otro);
        if (!f) { this.enviar(ws, { t: 'amigoerr', msg: 'No existe ninguna cuenta con ese nombre.' }); return; }
        const real = f.nombre;
        if (m.que === 'pedir') {
          const hay = this.sql.exec('SELECT estado FROM amigos WHERE (de = ? AND para = ?) OR (de = ? AND para = ?)', yo.name, real, real, yo.name).toArray();
          if (hay.length) {
            if (hay[0].estado === 'ok') { this.enviar(ws, { t: 'amigoerr', msg: 'Ya son amigos.' }); return; }
            this.sql.exec('UPDATE amigos SET estado = ? WHERE (de = ? AND para = ?) OR (de = ? AND para = ?)', 'ok', yo.name, real, real, yo.name);
            this.enviar(ws, { t: 'amigoerr', msg: '¡Listo, ahora son amigos!' });
          } else {
            this.sql.exec('INSERT INTO amigos (de, para, estado) VALUES (?, ?, ?)', yo.name, real, 'pendiente');
            this.enviar(ws, { t: 'amigoerr', msg: 'Solicitud enviada a ' + real + '.' });
          }
        }
        if (m.que === 'aceptar') this.sql.exec('UPDATE amigos SET estado = ? WHERE de = ? AND para = ?', 'ok', real, yo.name);
        if (m.que === 'rechazar' || m.que === 'borrar')
          this.sql.exec('DELETE FROM amigos WHERE (de = ? AND para = ?) OR (de = ? AND para = ?)', yo.name, real, real, yo.name);
        this.mandarAmigos(yo.name); this.mandarAmigos(real);
        break;
      }
      case 'invitar': {
        if (!yo.name) return;
        const otro = String(m.name || '').slice(0, 14);
        const code = String(m.code || '').toUpperCase();
        if (!/^[A-Z]{4}$/.test(code)) return;
        const son = this.sql.exec('SELECT 1 FROM amigos WHERE estado = ? AND ((de = ? AND para = ?) OR (de = ? AND para = ?))', 'ok', yo.name, otro, otro, yo.name).toArray();
        if (!son.length) { this.enviar(ws, { t: 'amigoerr', msg: 'Solo podés invitar a tus amigos.' }); return; }
        const w = this.socketDe(otro);
        if (!w) { this.enviar(ws, { t: 'amigoerr', msg: otro + ' no está conectado ahora.' }); return; }
        this.enviar(w, { t: 'invitacion', de: yo.name, code, junto: !!m.junto });
        this.enviar(ws, { t: 'amigoerr', msg: 'Invitación enviada a ' + otro + '.' });
        break;
      }
      case 'ping': this.enviar(ws, { t: 'pong', at: m.at }); break;
    }
  }
  webSocketClose(ws) { const n = this.datos(ws).name; if (n) setTimeout(() => this.avisarAmigos(), 50); }
  webSocketError() {}
}

/* ================= Sala: una partida ================= */
export class Sala {
  constructor(ctx, env) {
    this.ctx = ctx;
    this.env = env;
    this.code = null;
    this.playing = false;
    ctx.blockConcurrencyWhile(async () => {
      this.code = (await ctx.storage.get('code')) || null;
      this.playing = !!(await ctx.storage.get('playing'));
    });
  }

  async fetch(req) {
    const url = new URL(req.url);
    const code = (url.searchParams.get('code') || '').toUpperCase();
    if (code) { this.code = code; await this.ctx.storage.put('code', code); }
    if (req.headers.get('Upgrade') !== 'websocket') return new Response('Acá va un WebSocket', { status: 426 });

    const gente = this.ctx.getWebSockets().length;
    const par = new WebSocketPair();
    this.ctx.acceptWebSocket(par[1]);
    if (gente >= MAX_SALA) { this.enviar(par[1], { t: 'joinerr', msg: 'Esa sala ya está llena.' }); this.cerrar(par[1]); }
    else if (this.playing) { this.enviar(par[1], { t: 'joinerr', msg: 'En esa sala ya empezó la partida. Esperá a que termine.' }); this.cerrar(par[1]); }
    else {
      const id = ((await this.ctx.storage.get('seq')) || 0) + 1;
      await this.ctx.storage.put('seq', id);
      par[1].serializeAttachment({ id, name: '', pick: 'chispa', orden: id });
    }
    return new Response(null, { status: 101, webSocket: par[0] });
  }

  datos(ws) { try { return ws.deserializeAttachment() || {}; } catch (e) { return {}; } }
  guardar(ws, cambios) { const a = { ...this.datos(ws), ...cambios }; ws.serializeAttachment(a); return a; }
  enviar(ws, o) { try { ws.send(JSON.stringify(o)); } catch (e) {} }
  cerrar(ws) { try { ws.close(1000, 'sala'); } catch (e) {} }
  gente(menos) { return this.ctx.getWebSockets().filter(w => w !== menos && this.datos(w).name); }
  anfitrion(menos) {
    const l = this.gente(menos);
    return l.length ? l.reduce((a, b) => (this.datos(a).orden <= this.datos(b).orden ? a : b)) : null;
  }
  aTodos(o, menos) {
    const s = JSON.stringify(o);
    for (const w of this.gente(menos)) { try { w.send(s); } catch (e) {} }
  }
  roster(menos) {
    const h = this.anfitrion(menos), hid = h ? this.datos(h).id : null;
    const players = this.gente(menos).map(w => {
      const i = this.datos(w);
      return { id: i.id, name: i.name, pick: i.pick, lado: i.lado || null, host: i.id === hid };
    }).sort((a, b) => a.id - b.id);
    this.aTodos({ t: 'roster', players, host: hid, code: this.code }, menos);
  }
  async avisarLobby(menos) {
    const l = this.gente(menos), h = this.anfitrion(menos);
    const cuerpo = {
      code: this.code, host: h ? this.datos(h).name : '?',
      players: l.length, max: MAX_SALA, playing: this.playing, vacia: l.length === 0,
      nombres: l.map(w => this.datos(w).name)
    };
    try {
      const id = this.env.CUENTAS.idFromName('global');
      await this.env.CUENTAS.get(id).fetch('https://sala/aviso', { method: 'POST', body: JSON.stringify(cuerpo) });
    } catch (e) {}
  }

  async webSocketMessage(ws, raw) {
    if (typeof raw !== 'string' || raw.length > MAX_MSG) return;
    let m; try { m = JSON.parse(raw); } catch (e) { return; }
    const yo = this.datos(ws);

    if (m.t === 'hola') {                           // se presenta al entrar a la sala
      const i = this.guardar(ws, { name: String(m.name || 'Jugador').slice(0, 14), pick: typeof m.pick === 'string' ? m.pick : 'brasa',
        lado: m.lado && typeof m.lado.de === 'string' ? { de: m.lado.de.slice(0, 14), junto: !!m.lado.junto } : null });
      this.enviar(ws, { t: 'hello', id: i.id });    // dentro de la sala vale ESTE número, no el del lobby
      this.enviar(ws, { t: 'room', code: this.code });
      this.roster();
      await this.avisarLobby();
      return;
    }
    if (!yo.name) return;

    switch (m.t) {
      case 'me':
        if (typeof m.pick === 'string') this.guardar(ws, { pick: m.pick });
        this.roster();
        break;
      case 'start': {
        const h = this.anfitrion();
        if (!h || this.datos(h).id !== yo.id) return;
        this.playing = true; await this.ctx.storage.put('playing', true);
        this.aTodos({ t: 'start', roster: m.roster, modo: m.modo, mapa: m.mapa });
        await this.avisarLobby();
        break;
      }
      case 'state': {
        const h = this.anfitrion();
        if (!h || this.datos(h).id !== yo.id) return;
        this.aTodos(m, ws);
        break;
      }
      case 'input': {
        const h = this.anfitrion();
        if (!h || this.datos(h).id === yo.id) return;
        m.id = yo.id;
        this.enviar(h, m);
        break;
      }
      case 'result': {
        const h = this.anfitrion();
        if (!h || this.datos(h).id !== yo.id) return;
        this.playing = false; await this.ctx.storage.put('playing', false);
        this.aTodos({ t: 'matchend', winner: m.winner, players: m.players }, ws);
        try {
          const id = this.env.CUENTAS.idFromName('global');
          await this.env.CUENTAS.get(id).fetch('https://sala/resultado', { method: 'POST', body: JSON.stringify({ players: m.players }) });
        } catch (e) {}
        await this.avisarLobby();
        break;
      }
      case 'ping': this.enviar(ws, { t: 'pong', at: m.at }); break;
    }
  }

  async salida(ws) {
    const i = this.datos(ws);
    if (!i.name) return;
    const h = this.anfitrion();
    const eraHost = h && this.datos(h).id === i.id;
    this.aTodos({ t: 'left', id: i.id }, ws);
    if (eraHost && this.playing) this.aTodos({ t: 'hostgone' }, ws);
    if (eraHost) { this.playing = false; await this.ctx.storage.put('playing', false); }
    this.roster(ws);
    await this.avisarLobby(ws);
  }
  webSocketClose(ws) { this.salida(ws); }
  webSocketError(ws) { this.salida(ws); }
}

/* ================= el Worker ================= */
export default {
  async fetch(req, env) {
    const url = new URL(req.url);

    if (url.pathname === '/ws') {                                  // lobby: cuentas y lista de salas
      return env.CUENTAS.get(env.CUENTAS.idFromName('global')).fetch(req);
    }
    if (url.pathname.startsWith('/sala/')) {                        // una sala puntual
      const code = url.pathname.split('/')[2].toUpperCase().slice(0, 4);
      if (!/^[A-Z]{4}$/.test(code)) return new Response('Código inválido', { status: 400 });
      const destino = new URL(req.url); destino.searchParams.set('code', code);
      return env.SALAS.get(env.SALAS.idFromName(code)).fetch(new Request(destino, req));
    }
    if (url.pathname === '/salud') return json({ ok: true });
    return new Response(PAGINA, { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache' } });
  }
};


/* ---------- la pagina del juego ---------- */
